// ── بث صوتي نشط: أيقونة حمراء وامضة لكل البثوث ─────────────────────────────
function liveChannelForHost(hostId: string): string {
  const clean = String(hostId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48);
  if (clean) return `stooorna-live-${clean}`;
  let h = 0;
  const s = String(hostId || '');
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  const uid = Math.abs(h) % 100_000 || 1;
  return `stooorna-live-${uid}`;
}

function readLocalLiveActive(hostId: string): boolean {
  try {
    const raw = localStorage.getItem(`stooorna_live_active_${hostId}`);
    if (!raw) return false;
    const data = JSON.parse(raw) as { active?: boolean; at?: number };
    if (!data?.active) return false;
    if (data.at && Date.now() - data.at > 45_000) return false;
    return true;
  } catch {
    return false;
  }
}

function readLocalCamLiveActive(hostId: string): boolean {
  try {
    const raw = localStorage.getItem(`stooorna_livecam_active_${hostId}`);
    if (!raw) return false;
    const data = JSON.parse(raw) as { active?: boolean; at?: number };
    if (!data?.active) return false;
    if (data.at && Date.now() - data.at > 45_000) return false;
    return true;
  } catch {
    return false;
  }
}

function camChannelForHost(hostId: string): string {
  const clean = String(hostId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48);
  if (clean) return `stooorna-livecam-${clean}`;
  let h = 0;
  const s = String(hostId || '');
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  const uid = Math.abs(h) % 100_000 || 1;
  return `stooorna-livecam-${uid}`;
}

// ── مخزن مشترك لحالة البث: دائرة الهيدر + مستطيل الرئيسية يقرؤون منه نفس القرار،
// فيختفون مع بعض بنفس اللحظة بالضبط عند انتهاء البث (بعد مهلة تأكيد متواصلة). ──
const LIVE_SHARED_GRACE_MS = 45_000; // شبكة أمان فقط؛ الإنهاء الفعلي السريع (٣ ثواني) يتم بدليل مؤكد من داخل القناة
const liveShared = {
  seen: new Map<string, { kind: 'voice' | 'camera'; at: number }>(),
  held: new Map<string, 'voice' | 'camera'>(),
  roomEmpty: new Map<string, boolean>(), // آخر فحص من السيرفر: true = فاضي ومؤكد
  listeners: new Set<() => void>(),
  version: 0,
  paused: false,
  timer: 0 as any,
};
function liveSharedEmit() { liveShared.version++; liveShared.listeners.forEach(l => l()); }
function liveSharedMark(id: string, kind: 'voice' | 'camera') {
  const prev = liveShared.held.get(id);
  liveShared.seen.set(id, { kind, at: Date.now() });
  if (prev !== kind) { liveShared.held.set(id, kind); liveSharedEmit(); }
}
// إنهاء صريح: نستخدمه فقط لما يتأكد فعلاً أن صاحب البث طلع من القناة (دليلين متطابقين)
function liveSharedEnd(id: string) {
  liveShared.seen.delete(id);
  if (liveShared.held.delete(id)) liveSharedEmit();
}
function liveSharedIsHeld(id: string): boolean { return liveShared.held.has(id); }
function liveSharedKind(id: string): 'voice' | 'camera' | null { return liveShared.held.get(id) ?? null; }
// bonusMs: مهلة إضافية بعد الرجوع من صفحة البث، عشان اتصال المعاينة يلحق يثبّت أن البث لسا شغّال
function liveSharedTouchAll(bonusMs = 0) { const now = Date.now() + bonusMs; liveShared.seen.forEach(v => { v.at = now; }); }
function liveSharedSweep() {
  if (liveShared.paused) return;
  const now = Date.now();
  let changed = false;
  Array.from(liveShared.seen.entries()).forEach(([id, v]) => {
    if (now - v.at >= LIVE_SHARED_GRACE_MS) {
      liveShared.seen.delete(id);
      if (liveShared.held.delete(id)) changed = true;
    }
  });
  if (changed) liveSharedEmit();
}
function liveSharedSubscribe(fn: () => void) {
  liveShared.listeners.add(fn);
  if (!liveShared.timer) liveShared.timer = window.setInterval(liveSharedSweep, 500);
  return () => {
    liveShared.listeners.delete(fn);
    if (!liveShared.listeners.size && liveShared.timer) { window.clearInterval(liveShared.timer); liveShared.timer = 0; }
  };
}
function liveSharedSnapshot() { return liveShared.version; }
// كاش قوائم الأصدقاء/القصص: تنعرض فوراً عند الرجوع بدل ما تبدأ فاضية لين يرجع السيرفر
const headerListsCache: { uid: string; friends: any[]; stories: any[] } = { uid: '', friends: [], stories: [] };

/** Voice or camera live for this host. Returns kind for UI labels.
 *  sticky=true: يبقى البث ظاهراً حتى يتأكد انتهاؤه لمدة متواصلة (تجاوز أي انقطاع لحظي). */
function useLiveBroadcastKind(hostId: string | null | undefined, sticky = false): 'voice' | 'camera' | null {
  const [kind, setKind] = useState<'voice' | 'camera' | null>(null);
  const sharedVer = useSyncExternalStore(liveSharedSubscribe, liveSharedSnapshot, liveSharedSnapshot);

  useEffect(() => {
    if (!hostId) {
      setKind(null);
      return;
    }
    let cancelled = false;
    const channel = liveChannelForHost(hostId);
    const camChannel = camChannelForHost(hostId);

    const apply = (v: 'voice' | 'camera' | null) => {
      if (cancelled) return;
      if (!sticky) { setKind(v); return; }
      // وضع sticky: نسجّل الحضور فقط، والاختفاء يقرره المخزن المشترك (مع المستطيل بنفس اللحظة)
      if (v) liveSharedMark(String(hostId), v);
    };

    const checkLocal = (): 'voice' | 'camera' | null => {
      if (readLocalCamLiveActive(hostId)) return 'camera';
      if (readLocalLiveActive(hostId)) return 'voice';
      return null;
    };

    const checkRoom = async () => {
      const local = checkLocal();
      if (local) apply(local);
      try {
        const rCam = await fetch(`/api/room?id=${encodeURIComponent(camChannel)}`, { credentials: 'include' });
        if (rCam.ok) {
          const data = await rCam.json() as { members?: unknown[] };
          const n = Array.isArray(data.members) ? data.members.length : 0;
          if (n > 0) {
            apply('camera');
            return;
          }
        }
      } catch { /* ignore */ }
      try {
        const r = await fetch(`/api/room?id=${encodeURIComponent(channel)}`, { credentials: 'include' });
        if (!r.ok) {
          apply(checkLocal());
          return;
        }
        const data = await r.json() as { members?: unknown[] };
        const n = Array.isArray(data.members) ? data.members.length : 0;
        if (n > 0) apply('voice');
        else apply(checkLocal());
      } catch {
        apply(checkLocal());
      }
    };

    checkRoom();
    const interval = window.setInterval(checkRoom, sticky ? 1000 : 2500);

    const onEvt = (e: Event) => {
      const d = (e as CustomEvent).detail as { hostId?: string; active?: boolean; kind?: string } | undefined;
      if (!d || !d.hostId) return;
      if (String(d.hostId) !== String(hostId)) return;
      if (!d.active) {
        void checkRoom();
        return;
      }
      if (d.kind === 'camera' || (e.type || '').includes('livecam')) apply('camera');
      else apply(checkLocal() || 'voice');
    };
    window.addEventListener('stooorna:live-active', onEvt);
    window.addEventListener('stooorna:livecam-active', onEvt);

    const onStorage = (e: StorageEvent) => {
      if (e.key === `stooorna_live_active_${hostId}` || e.key === `stooorna_livecam_active_${hostId}`) {
        void checkRoom();
      }
    };
    window.addEventListener('storage', onStorage);

    return () => {
      cancelled = true;
      window.clearInterval(interval);
      window.removeEventListener('stooorna:live-active', onEvt);
      window.removeEventListener('stooorna:livecam-active', onEvt);
      window.removeEventListener('storage', onStorage);
    };
  }, [hostId]);

  void sharedVer;
  if (sticky) return hostId ? liveSharedKind(String(hostId)) : null;
  return kind;
}


/** أي مستخدم من القائمة في بث (صوتي/مرئي) الآن؟ — يتحدّث فوراً بحدث البث، ويتحقق دورياً من الغرف. */
function useAnyLiveBroadcast(hostIds: string[]): boolean {
  const [any, setAny] = useState(false);
  const key = Array.from(new Set(hostIds.filter(Boolean).map(String))).sort().join('|');

  useEffect(() => {
    const ids = key ? key.split('|') : [];
    let cancelled = false;
    const apply = (v: boolean) => { if (!cancelled) setAny(prev => (prev === v ? prev : v)); };
    const localAny = () => ids.some(id => readLocalCamLiveActive(id) || readLocalLiveActive(id));
    if (localAny()) apply(true);

    let busy = false;
    const check = async () => {
      if (busy) return;
      busy = true;
      try {
        if (localAny()) { apply(true); return; }
        const hasMembers = async (channel: string) => {
          try {
            const r = await fetch(`/api/room?id=${encodeURIComponent(channel)}`, { credentials: 'include' });
            if (!r.ok) return false;
            const d = await r.json() as { members?: unknown[] };
            return Array.isArray(d.members) && d.members.length > 0;
          } catch { return false; }
        };
        const results = await Promise.all(ids.map(async id => (
          (await hasMembers(camChannelForHost(id))) || (await hasMembers(liveChannelForHost(id)))
        )));
        apply(results.some(Boolean));
      } finally { busy = false; }
    };
    void check();
    const interval = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      void check();
    }, 2000);

    // بمجرد فتح لايف: النقطة تصير خضراء مباشرة بدون انتظار الفحص الدوري
    const onEvt = (e: Event) => {
      const d = (e as CustomEvent).detail as { hostId?: string; active?: boolean } | undefined;
      if (d?.active) apply(true);
      else void check();
    };
    const onStorage = (e: StorageEvent) => {
      if (e.key && (e.key.startsWith('stooorna_live_active_') || e.key.startsWith('stooorna_livecam_active_'))) void check();
    };
    window.addEventListener('stooorna:live-active', onEvt);
    window.addEventListener('stooorna:livecam-active', onEvt);
    window.addEventListener('storage', onStorage);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      window.removeEventListener('stooorna:live-active', onEvt);
      window.removeEventListener('stooorna:livecam-active', onEvt);
      window.removeEventListener('storage', onStorage);
    };
  }, [key]);

  return any;
}


// ── مؤشّر "في مكالمة الآن" العام ─────────────────────────────────────────────
// كل مستخدم داخل مكالمة يعلن حضوره في غرفة خفيفة `stooorna-incall-<userId>` (join + heartbeat)،
// وأي شخص يقدر يعرف أن في مكالمات شغّالة في التطبيق بدون ما تكون المكالمة معه.
function inCallRoomId(userId: string): string {
  const clean = String(userId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48);
  return `stooorna-incall-${clean || 'x'}`;
}
function readLocalInCallActive(userId: string): boolean {
  try {
    const raw = localStorage.getItem(`stooorna_incall_active_${userId}`);
    if (!raw) return false;
    const data = JSON.parse(raw) as { active?: boolean; at?: number };
    if (!data?.active) return false;
    if (data.at && Date.now() - data.at > 15_000) return false;
    return true;
  } catch { return false; }
}
function usePublishInCall(userId: string | null | undefined, active: boolean) {
  useEffect(() => {
    if (!userId || !active) return;
    const uid = String(userId);
    const roomId = inCallRoomId(uid);
    const post = (path: string) => {
      try {
        void fetch(path, {
          method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ roomId, userId: uid, name: 'incall' }),
          keepalive: true,
        }).catch(() => {});
      } catch { /* */ }
    };
    const mark = (on: boolean) => {
      try {
        localStorage.setItem(`stooorna_incall_active_${uid}`, JSON.stringify({ active: on, at: Date.now() }));
        window.dispatchEvent(new CustomEvent('stooorna:incall-active', { detail: { userId: uid, active: on } }));
      } catch { /* */ }
    };
    post('/api/room/join');
    mark(true);
    const beat = window.setInterval(() => { post('/api/room/heartbeat'); mark(true); }, 4000);
    return () => {
      window.clearInterval(beat);
      post('/api/room/leave');
      mark(false);
    };
  }, [userId, active]);
}
/** أي مستخدم من القائمة (أو أنا) في مكالمة الآن؟ */
function useAnyInCall(hostIds: string[]): boolean {
  const [any, setAny] = useState(false);
  const key = Array.from(new Set(hostIds.filter(Boolean).map(String))).sort().join('|');
  useEffect(() => {
    const ids = key ? key.split('|') : [];
    let cancelled = false;
    const apply = (v: boolean) => { if (!cancelled) setAny(prev => (prev === v ? prev : v)); };
    const localAny = () => ids.some(readLocalInCallActive);
    if (localAny()) apply(true);
    let busy = false;
    const check = async () => {
      if (busy) return;
      busy = true;
      try {
        if (localAny()) { apply(true); return; }
        const res = await Promise.all(ids.map(async id => {
          try {
            const r = await fetch(`/api/room?id=${encodeURIComponent(inCallRoomId(id))}`, { credentials: 'include' });
            if (!r.ok) return false;
            const d = await r.json() as { members?: unknown[] };
            return Array.isArray(d.members) && d.members.length > 0;
          } catch { return false; }
        }));
        apply(res.some(Boolean));
      } finally { busy = false; }
    };
    void check();
    const interval = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      void check();
    }, 2000);
    const onEvt = (e: Event) => {
      const d = (e as CustomEvent).detail as { active?: boolean } | undefined;
      if (d?.active) apply(true); else void check();
    };
    const onStorage = (e: StorageEvent) => { if (e.key && e.key.startsWith('stooorna_incall_active_')) void check(); };
    window.addEventListener('stooorna:incall-active', onEvt);
    window.addEventListener('storage', onStorage);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      window.removeEventListener('stooorna:incall-active', onEvt);
      window.removeEventListener('storage', onStorage);
    };
  }, [key]);
  return any;
}

// ── حضور أونلاين سريع (مسار موازٍ لـ usePresenceQuery — لا يستبدله) ──────────────
// كل مستخدم متصل يعلن حضوره في غرفة خفيفة `stooorna-online-<userId>` (join + heartbeat كل 4ث)،
// وأي شخص يفحص غرف المضافين كل ثانيتين، فتتحول النقطة للأخضر مباشرة بدل انتظار دورة الحضور.
function onlineRoomId(userId: string): string {
  const clean = String(userId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48);
  return `stooorna-online-${clean || 'x'}`;
}
function usePublishOnline(userId: string | null | undefined) {
  useEffect(() => {
    if (!userId) return;
    const uid = String(userId);
    const roomId = onlineRoomId(uid);
    const post = (path: string, keepalive = true) => {
      try {
        void fetch(path, {
          method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ roomId, userId: uid, name: 'online' }),
          keepalive,
        }).catch(() => {});
      } catch { /* */ }
    };
    const mark = (on: boolean) => {
      try {
        localStorage.setItem(`stooorna_online_${uid}`, JSON.stringify({ active: on, at: Date.now() }));
        window.dispatchEvent(new CustomEvent('stooorna:online-active', { detail: { userId: uid, active: on } }));
      } catch { /* */ }
    };
    post('/api/room/join');
    mark(true);
    const beat = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      post('/api/room/heartbeat'); mark(true);
    }, 4000);
    const onVis = () => { if (document.visibilityState === 'visible') { post('/api/room/join'); mark(true); } };
    document.addEventListener('visibilitychange', onVis);
    const onLeave = () => post('/api/room/leave');
    window.addEventListener('pagehide', onLeave);
    return () => {
      window.clearInterval(beat);
      document.removeEventListener('visibilitychange', onVis);
      window.removeEventListener('pagehide', onLeave);
      post('/api/room/leave');
      mark(false);
    };
  }, [userId]);
}
/** أي واحد من المعرّفات (غير أنا) أونلاين الآن؟ */
function useAnyOnline(hostIds: string[], selfId?: string | null): boolean {
  const [any, setAny] = useState(false);
  const key = Array.from(new Set(hostIds.filter(Boolean).map(String))).filter(id => id !== String(selfId || '')).sort().join('|');
  useEffect(() => {
    const ids = key ? key.split('|') : [];
    let cancelled = false;
    const apply = (v: boolean) => { if (!cancelled) setAny(prev => (prev === v ? prev : v)); };
    const localAny = () => ids.some(id => {
      try {
        const raw = localStorage.getItem(`stooorna_online_${id}`);
        if (!raw) return false;
        const d = JSON.parse(raw) as { active?: boolean; at?: number };
        return !!d?.active && !!d.at && Date.now() - d.at < 12_000;
      } catch { return false; }
    });
    if (ids.length === 0) { apply(false); return; }
    if (localAny()) apply(true);
    let busy = false;
    const check = async () => {
      if (busy) return;
      busy = true;
      try {
        if (localAny()) { apply(true); return; }
        const res = await Promise.all(ids.map(async id => {
          try {
            const r = await fetch(`/api/room?id=${encodeURIComponent(onlineRoomId(id))}`, { credentials: 'include' });
            if (!r.ok) return false;
            const d = await r.json() as { members?: unknown[] };
            return Array.isArray(d.members) && d.members.length > 0;
          } catch { return false; }
        }));
        apply(res.some(Boolean));
      } finally { busy = false; }
    };
    void check();
    const interval = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      void check();
    }, 2000);
    const onEvt = (e: Event) => {
      const d = (e as CustomEvent).detail as { userId?: string; active?: boolean } | undefined;
      if (d?.active && d.userId && ids.includes(String(d.userId))) apply(true); else void check();
    };
    const onStorage = (e: StorageEvent) => { if (e.key && e.key.startsWith('stooorna_online_')) void check(); };
    window.addEventListener('stooorna:online-active', onEvt);
    window.addEventListener('storage', onStorage);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      window.removeEventListener('stooorna:online-active', onEvt);
      window.removeEventListener('storage', onStorage);
    };
  }, [key]);
  return any;
}

/** أي صديق (غيري) ظاهر على الخريطة الحية الآن؟ — نفس مصدر الخريطة (/api/live-gps + الكاش المحلي) وبنفس مدة الصلاحية. */
function useAnyOnMap(friendIds: string[], selfId?: string | null): boolean {
  const [any, setAny] = useState(false);
  const key = Array.from(new Set(friendIds.filter(Boolean).map(String))).filter(id => id !== String(selfId || '')).sort().join('|');
  useEffect(() => {
    const ids = new Set(key ? key.split('|') : []);
    let cancelled = false;
    const apply = (v: boolean) => { if (!cancelled) setAny(prev => (prev === v ? prev : v)); };
    if (ids.size === 0) { apply(false); return; }
    const fresh = (p: any) => p && typeof p.lat === 'number' && Date.now() - Number(p.at || Date.now()) < 30 * 60 * 1000;
    const localAny = () => {
      try {
        const raw = JSON.parse(localStorage.getItem('stooorna_live_gps_pins') || '{}') as Record<string, any>;
        return Object.values(raw).some(p => p && ids.has(String(p.id)) && fresh(p));
      } catch { return false; }
    };
    if (localAny()) apply(true);
    let busy = false;
    const check = async () => {
      if (busy) return;
      busy = true;
      try {
        if (localAny()) { apply(true); return; }
        const r = await fetch('/api/live-gps', { credentials: 'include' });
        if (!r.ok) { apply(false); return; }
        const d = await r.json() as { pins?: any[] };
        apply(Array.isArray(d.pins) && d.pins.some(p => p && ids.has(String(p.id)) && fresh(p)));
      } catch { /* keep last value */ } finally { busy = false; }
    };
    void check();
    const interval = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      void check();
    }, 3000);
    const onStorage = (e: StorageEvent) => { if (e.key === 'stooorna_live_gps_pins') void check(); };
    window.addEventListener('storage', onStorage);
    return () => { cancelled = true; window.clearInterval(interval); window.removeEventListener('storage', onStorage); };
  }, [key]);
  return any;
}

/** مجموعة معرّفات المضافين الأونلاين الآن (لعدّادات أونلاين/أوفلاين داخل الخريطة). */
function useOnlineIdSet(ids: string[], enabled = true): Set<string> {
  const [online, setOnline] = useState<Set<string>>(() => new Set());
  const key = Array.from(new Set(ids.filter(Boolean).map(String))).sort().join('|');
  useEffect(() => {
    const list = enabled && key ? key.split('|') : [];
    let cancelled = false;
    if (list.length === 0) { setOnline(prev => (prev.size ? new Set() : prev)); return; }
    const localOn = (id: string) => {
      try {
        const raw = localStorage.getItem(`stooorna_online_${id}`);
        if (!raw) return false;
        const d = JSON.parse(raw) as { active?: boolean; at?: number };
        return !!d?.active && !!d.at && Date.now() - d.at < 12_000;
      } catch { return false; }
    };
    let busy = false;
    const check = async () => {
      if (busy) return;
      busy = true;
      try {
        const flags = await Promise.all(list.map(async id => {
          if (localOn(id)) return true;
          try {
            const r = await fetch(`/api/room?id=${encodeURIComponent(onlineRoomId(id))}`, { credentials: 'include' });
            if (!r.ok) return false;
            const d = await r.json() as { members?: unknown[] };
            return Array.isArray(d.members) && d.members.length > 0;
          } catch { return false; }
        }));
        if (cancelled) return;
        const next = new Set(list.filter((_, i) => flags[i]));
        setOnline(prev => (prev.size === next.size && [...next].every(x => prev.has(x)) ? prev : next));
      } finally { busy = false; }
    };
    void check();
    const iv = window.setInterval(() => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      void check();
    }, 3000);
    const onEvt = () => { void check(); };
    window.addEventListener('stooorna:online-active', onEvt);
    return () => { cancelled = true; window.clearInterval(iv); window.removeEventListener('stooorna:online-active', onEvt); };
  }, [key, enabled]);
  return online;
}

/** نفس مسار عدّادات الخريطة الأصلية (LiveLocationMap): pullLiveLocations + pullOnlineIds كل 4 ثوانٍ. */
function useLiveMapPresence(enabled = true): { liveIds: Set<string>; onlineIds: Set<string> } {
  const [state, setState] = useState<{ liveIds: Set<string>; onlineIds: Set<string> }>(() => ({ liveIds: new Set(), onlineIds: new Set() }));
  useEffect(() => {
    if (!enabled) return;
    let stop = false;
    const same = (a: Set<string>, b: Set<string>) => a.size === b.size && [...a].every(x => b.has(x));
    const tick = async () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      try {
        const [pings, onl] = await Promise.all([pullLiveLocations(), pullOnlineIds()]);
        if (stop) return;
        const liveIds = new Set<string>((pings || []).filter((p: any) => p && Number.isFinite(p.lat) && Number.isFinite(p.lng)).map((p: any) => String(p.id)));
        const onlineIds = new Set<string>(Array.from(onl as Iterable<unknown> || []).map(x => String(x)));
        setState(prev => (same(prev.liveIds, liveIds) && same(prev.onlineIds, onlineIds) ? prev : { liveIds, onlineIds }));
      } catch { /* keep last */ }
    };
    void tick();
    const iv = window.setInterval(tick, 4000);
    return () => { stop = true; window.clearInterval(iv); };
  }, [enabled]);
  return state;
}

function anyFriendOnMapPins_(
  friendIds: string[], selfId: string,
  sync: { liveIds: Set<string>; onlineIds: Set<string> },
  roomOnline: Set<string>, presence: Record<string, any> | undefined, pinsFlag: boolean,
): boolean {
  if (pinsFlag) return true;
  const pool = new Set<string>([...friendIds.map(String), ...sync.liveIds]);
  pool.delete(selfId);
  for (const id of pool) {
    if (sync.liveIds.has(id) || sync.onlineIds.has(id) || roomOnline.has(id) || presence?.[id]?.online) return true;
  }
  return false;
}

// ── Notification sound design — small synthesized tones (water-drop / bubble mixes) ──
// No audio files needed: each event gets its own tiny Web Audio mix so the tones stay distinct.
let sfxCtx: AudioContext | null = null;
function getSfxCtx(): AudioContext | null {
  try {
    if (!sfxCtx) {
      const Ctx: typeof AudioContext | undefined = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (!Ctx) return null;
      sfxCtx = new Ctx();
    }
    if (sfxCtx.state === 'suspended') void sfxCtx.resume();
    return sfxCtx;
  } catch { return null; }
}
function sfxTone(ctx: AudioContext, startTime: number, freq: number, duration: number, opts: { type?: OscillatorType; peakGain?: number; glideTo?: number } = {}) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = opts.type ?? 'sine';
  osc.frequency.setValueAtTime(freq, startTime);
  if (opts.glideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(opts.glideTo, 20), startTime + duration);
  gain.gain.setValueAtTime(0.0001, startTime);
  gain.gain.exponentialRampToValueAtTime(opts.peakGain ?? 0.22, startTime + Math.min(0.03, duration * 0.25));
  gain.gain.exponentialRampToValueAtTime(0.0001, startTime + duration);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(startTime);
  osc.stop(startTime + duration + 0.03);
}
/** نشر بوست جديد — نقرتا "قطرة ماء" صاعدتان ولمّاعتان */
function playNewPostSound() {
  const ctx = getSfxCtx();
  if (!ctx) return;
  const t = ctx.currentTime;
  sfxTone(ctx, t, 1100, 0.16, { type: 'sine', peakGain: 0.26, glideTo: 550 });
  sfxTone(ctx, t + 0.1, 1500, 0.18, { type: 'sine', peakGain: 0.26, glideTo: 720 });
}
/** إشعار وصول محتوى جديد (بانر New Post) — رنة جرسية ناعمة بنغمتين */
function playNotificationSound() {
  const ctx = getSfxCtx();
  if (!ctx) return;
  const t = ctx.currentTime;
  sfxTone(ctx, t, 1320, 0.32, { type: 'sine', peakGain: 0.2 });
  sfxTone(ctx, t, 1324, 0.32, { type: 'sine', peakGain: 0.12 });
  sfxTone(ctx, t + 0.16, 990, 0.3, { type: 'sine', peakGain: 0.16 });
}
/** وصول مسج شير — "قطرة تسقط" ثم "فقاعة" صغيرة تصعد */
function playShareArrivedSound() {
  const ctx = getSfxCtx();
  if (!ctx) return;
  const t = ctx.currentTime;
  sfxTone(ctx, t, 700, 0.14, { type: 'sine', peakGain: 0.24, glideTo: 260 });
  sfxTone(ctx, t + 0.12, 340, 0.22, { type: 'triangle', peakGain: 0.18, glideTo: 680 });
}
/** وجود أحد على المايك — نقرة جرس هاتف قصيرة، أقل من ثانيتين، تُشغَّل مرة واحدة وتختفي */
/** رنة اتصال واردة — نغمة "رنين جوال" حقيقية: مقطع سريع من أربع نغمات صاعدة (زي رنات
 *  الجوالات الافتراضية)، يتكرر مرتين متتاليتين لكل دفعة رنين. الدفعة نفسها تتكرر من الخارج
 *  (انظر ringIntervalRef بمكوّن GlobeVoiceControl) لين يرد المستخدم أو ينقطع الاتصال */
function playIncomingCallRing() {
  const ctx = getSfxCtx();
  if (!ctx) return;
  const t = ctx.currentTime;
  const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6
  const playTrill = (start: number) => {
    notes.forEach((freq, i) => {
      sfxTone(ctx, start + i * 0.09, freq, 0.16, { type: 'triangle', peakGain: 0.26 });
    });
  };
  playTrill(t);
  playTrill(t + 0.42);
}

// ── ScVoiceBubble — voice player for secret chat ──────────────────────────────
const SC_BARS = 24;
// ═══════════════════════════════════════════════════════════════════════════
// Secret-chat studio — round record button (hold = record, tap = audio/video),
// round video notes (normal / view-once) and the "dust" delete effect.
// ═══════════════════════════════════════════════════════════════════════════
const SC_VNOTE_PREFIX = 'vnote';
const SC_LEGACY_MIC = false; // the old hold-to-record mic button is kept in the file but replaced by <ScRecordButton/>
const SC_ONCE_KEY = 'stooorna_sc_once_viewed_v1';
const SC_HIDDEN_KEY = 'stooorna_sc_hidden_msgs_v1';
const SC_REC_MODE_KEY = 'stooorna_sc_rec_mode_v1';
const SC_REC_ONCE_KEY = 'stooorna_sc_rec_once_v1';
const SC_VNOTE_MAX_SECS = 60;

function scReadSet(key: string): Set<string> {
  try {
    const raw = localStorage.getItem(key);
    const arr = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(arr) ? arr.map(String) : []);
  } catch { return new Set(); }
}
function scWriteSet(key: string, s: Set<string>) {
  try { localStorage.setItem(key, JSON.stringify(Array.from(s).slice(-2000))); } catch { /* ignore */ }
}
function scOnceViewed(k: string): boolean { return scReadSet(SC_ONCE_KEY).has(k); }
function scMarkOnceViewed(k: string) { const s = scReadSet(SC_ONCE_KEY); s.add(k); scWriteSet(SC_ONCE_KEY, s); }
function scLoadHiddenIds(): Set<number> {
  return new Set(Array.from(scReadSet(SC_HIDDEN_KEY)).map(Number).filter(n => Number.isFinite(n)));
}
function scSaveHiddenIds(s: Set<number>) { scWriteSet(SC_HIDDEN_KEY, new Set(Array.from(s).map(String))); }
function scFmtSecs(s: number): string { return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`; }

// The video-note flavour travels inside the uploaded file name (vnote-12s-<ts>.webm / vnote-once-12s-<ts>.webm)
// so no server change is needed to tell a round note (and view-once) from a normal video.
function scParseVideoNote(name?: string, url?: string): { once: boolean; secs: number } | null {
  const m = /vnote(-once)?-(\d+)s-\d+/.exec(`${name || ''} ${url || ''}`);
  if (!m) return null;
  return { once: !!m[1], secs: Number(m[2]) || 0 };
}

type ScDustParticle = { sx: number; sy: number; x0: number; y0: number; delay: number; life: number; vx: number; vy: number; ph: number; amp: number };

// Disintegration ("dust") effect: the element is cut into small tiles that break away left -> right,
// drift up/outwards and fade. Pure canvas drawImage (never reads pixels, so cross-origin video is fine).
function scRunDust(rect: DOMRect, video: HTMLVideoElement | null, round: boolean, done: () => void) {
  const pad = 110;
  const W = Math.max(8, Math.round(rect.width));
  const H = Math.max(8, Math.round(rect.height));
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const canvas = document.createElement('canvas');
  canvas.width = Math.round((W + pad * 2) * dpr);
  canvas.height = Math.round((H + pad * 2) * dpr);
  const cs = canvas.style;
  cs.position = 'fixed';
  cs.left = `${rect.left - pad}px`;
  cs.top = `${rect.top - pad}px`;
  cs.width = `${W + pad * 2}px`;
  cs.height = `${H + pad * 2}px`;
  cs.pointerEvents = 'none';
  cs.zIndex = '2147483000';
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');
  const src = document.createElement('canvas');
  src.width = W; src.height = H;
  const sctx = src.getContext('2d');
  if (!ctx || !sctx) { canvas.remove(); done(); return; }
  ctx.scale(dpr, dpr);
  const grad = sctx.createLinearGradient(0, 0, W, H);
  grad.addColorStop(0, '#0f3a44'); grad.addColorStop(1, '#061418');
  sctx.fillStyle = grad; sctx.fillRect(0, 0, W, H);
  try {
    if (video && video.readyState >= 2 && video.videoWidth > 0) {
      const k = Math.max(W / video.videoWidth, H / video.videoHeight);
      const dw = video.videoWidth * k, dh = video.videoHeight * k;
      sctx.drawImage(video, (W - dw) / 2, (H - dh) / 2, dw, dh);
    }
  } catch { /* keep the gradient snapshot */ }
  const s = Math.max(4, Math.round(Math.min(W, H) / 30));
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2;
  const parts: ScDustParticle[] = [];
  for (let y = 0; y < H; y += s) {
    for (let x = 0; x < W; x += s) {
      const mx = x + s / 2, my = y + s / 2;
      if (round && Math.hypot(mx - cx, my - cy) > R) continue;
      parts.push({
        sx: x, sy: y, x0: mx, y0: my,
        delay: (x / W) * 0.6 + Math.random() * 0.15,
        life: 0.8 + Math.random() * 0.6,
        vx: 25 + Math.random() * 110,
        vy: -(15 + Math.random() * 100),
        ph: Math.random() * 6.28,
        amp: 3 + Math.random() * 6,
      });
    }
  }
  try { navigator.vibrate?.(20); } catch { /* ignore */ }
  const t0 = performance.now();
  const frame = (now: number) => {
    const t = (now - t0) / 1000;
    ctx.clearRect(0, 0, W + pad * 2, H + pad * 2);
    let alive = false;
    for (const p of parts) {
      const lt = t - p.delay;
      if (lt < 0) {
        alive = true;
        ctx.globalAlpha = 1;
        ctx.drawImage(src, p.sx, p.sy, s, s, p.sx + pad, p.sy + pad, s, s);
        continue;
      }
      if (lt > p.life) continue;
      alive = true;
      const k = lt / p.life;
      const px = p.x0 + p.vx * lt + Math.sin(lt * 7 + p.ph) * p.amp * k;
      const py = p.y0 + p.vy * lt - 30 * lt * lt;
      const sz = s * (1 - 0.65 * k);
      ctx.globalAlpha = Math.max(0, 1 - k * k);
      ctx.drawImage(src, p.sx, p.sy, s, s, px + pad - sz / 2, py + pad - sz / 2, sz, sz);
    }
    ctx.globalAlpha = 1;
    if (alive) requestAnimationFrame(frame);
    else { canvas.remove(); done(); }
  };
  frame(t0); // paint the first frame synchronously so there is no flicker when the real element is hidden
  requestAnimationFrame(frame);
}

// Long-press a video -> "delete?" dialog -> the video crumbles into dust and is deleted.
function ScVideoDeleteFx({ enabled, round, onDelete, children }: {
  enabled: boolean;
  round: boolean;
  onDelete: () => void | Promise<void>;
  children: React.ReactNode;
}) {
  const boxRef = useRef<HTMLDivElement | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startRef = useRef({ x: 0, y: 0 });
  const firedAtRef = useRef(0);
  const mountedRef = useRef(true);
  const [confirm, setConfirm] = useState(false);
  const [bursting, setBursting] = useState(false);
  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; if (timerRef.current) clearTimeout(timerRef.current); };
  }, []);
  const clear = () => { if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; } };
  const onDown = (e: React.PointerEvent) => {
    if (!enabled || bursting) return;
    startRef.current = { x: e.clientX, y: e.clientY };
    clear();
    timerRef.current = setTimeout(() => {
      timerRef.current = null;
      firedAtRef.current = Date.now();
      try { navigator.vibrate?.(12); } catch { /* ignore */ }
      setConfirm(true);
    }, 480);
  };
  const onMove = (e: React.PointerEvent) => {
    if (!timerRef.current) return;
    if (Math.hypot(e.clientX - startRef.current.x, e.clientY - startRef.current.y) > 10) clear();
  };
  const runDelete = () => {
    setConfirm(false);
    const el = boxRef.current;
    if (!el) { void onDelete(); return; }
    const rect = el.getBoundingClientRect();
    const vid = el.querySelector('video') as HTMLVideoElement | null;
    setBursting(true);
    scRunDust(rect, vid, round, () => {
      void Promise.resolve(onDelete()).finally(() => { if (mountedRef.current) setBursting(false); });
    });
  };
  return (
    <>
      <div
        ref={boxRef}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={clear}
        onPointerCancel={clear}
        onPointerLeave={clear}
        onContextMenu={e => { if (enabled) e.preventDefault(); }}
        onClickCapture={e => { if (Date.now() - firedAtRef.current < 700) { e.stopPropagation(); e.preventDefault(); } }}
        style={{
          display: 'inline-block', position: 'relative',
          visibility: bursting ? 'hidden' : 'visible',
          userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none',
        } as React.CSSProperties}
      >
        {children}
      </div>
      {confirm && createPortal(
        <div
          onClick={() => setConfirm(false)}
          style={{ position: 'fixed', inset: 0, zIndex: 2147483100, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{ background: '#14191c', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 16, padding: '20px 18px 12px', width: '100%', maxWidth: 300, direction: 'rtl' }}
          >
            <p style={{ margin: '0 0 6px', color: '#fff', fontWeight: 700, fontSize: '0.95rem' }}>حذف الفيديو</p>
            <p style={{ margin: '0 0 14px', color: 'rgba(255,255,255,0.65)', fontSize: '0.82rem', lineHeight: 1.5 }}>متأكد تبي تحذف هذا الفيديو؟</p>
            <div style={{ display: 'flex', gap: 6, justifyContent: 'flex-start' }}>
              <button type="button" onClick={runDelete} style={{ background: 'none', border: 'none', color: '#ef4444', fontWeight: 700, fontSize: '0.88rem', padding: '8px 14px', cursor: 'pointer' }}>حذف</button>
              <button type="button" onClick={() => setConfirm(false)} style={{ background: 'none', border: 'none', color: CLR_PRIMARY, fontWeight: 700, fontSize: '0.88rem', padding: '8px 14px', cursor: 'pointer' }}>إلغاء</button>
            </div>
          </div>
        </div>,
        document.body
      )}
    </>
  );
}

// Full-screen player for a view-once note: plays once, then the note is gone for this user.
function ScOnceViewer({ url, onClose }: { url: string; onClose: () => void }) {
  const vRef = useRef<HTMLVideoElement | null>(null);
  const [prog, setProg] = useState(0);
  useEffect(() => {
    const v = vRef.current;
    if (!v) return;
    v.muted = false;
    v.play().catch(() => { try { v.muted = true; void v.play(); } catch { /* ignore */ } });
  }, []);
  const size = Math.min(340, Math.round(window.innerWidth * 0.78));
  const r = size / 2 - 3;
  const C = 2 * Math.PI * r;
  return createPortal(
    <div style={{ position: 'fixed', inset: 0, zIndex: 2147483050, background: 'rgba(0,0,0,0.94)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 18 }}>
      <button
        type="button" aria-label="إغلاق" onClick={onClose}
        style={{ position: 'absolute', top: 'max(16px, env(safe-area-inset-top))', right: 16, width: 40, height: 40, borderRadius: '50%', border: 'none', background: 'rgba(255,255,255,0.12)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}
      >
        <X size={20} />
      </button>
      <div style={{ position: 'relative', width: size, height: size, borderRadius: '50%', overflow: 'hidden', background: '#000' }}>
        <video
          ref={vRef} src={url} playsInline controlsList="nodownload" disablePictureInPicture
          onContextMenu={e => e.preventDefault()}
          onTimeUpdate={e => { const v = e.currentTarget; if (v.duration) setProg(v.currentTime / v.duration); }}
          onEnded={onClose}
          style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
        />
        <svg width={size} height={size} style={{ position: 'absolute', inset: 0, pointerEvents: 'none', transform: 'rotate(-90deg)' }}>
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={CLR_PRIMARY} strokeWidth={3} strokeLinecap="round" strokeDasharray={C} strokeDashoffset={C * (1 - prog)} />
        </svg>
      </div>
      <p style={{ margin: 0, color: 'rgba(255,255,255,0.6)', fontSize: '0.78rem', direction: 'rtl' }}>مرة واحدة — بيختفي بعد المشاهدة</p>
    </div>,
    document.body
  );
}

// The round video message. Normal: a looping muted circle, tap = play with sound. Once: a sealed "Open" circle.
function ScVideoNote({ url, once, isMe, viewedKey, secs, onDelete }: {
  url: string;
  once: boolean;
  isMe: boolean;
  viewedKey: string;
  secs: number;
  onDelete: () => void | Promise<void>;
}) {
  const SIZE = 190;
  const vidRef = useRef<HTMLVideoElement | null>(null);
  const [muted, setMuted] = useState(true);
  const [paused, setPaused] = useState(false);
  const [prog, setProg] = useState(0);
  const [viewed, setViewed] = useState<boolean>(() => (once && !isMe ? scOnceViewed(viewedKey) : false));
  const [open, setOpen] = useState(false);

  if (once) {
    const sealed = !isMe && !viewed;
    return (
      <>
        <ScVideoDeleteFx enabled={isMe} round onDelete={onDelete}>
          <div
            role="button"
            aria-label={sealed ? 'Open' : 'مرة واحدة'}
            onClick={() => {
              if (!sealed) return;
              scMarkOnceViewed(viewedKey);
              setViewed(true);
              setOpen(true);
            }}
            style={{
              width: 132, height: 132, borderRadius: '50%',
              border: sealed ? `2px dashed ${CLR_PRIMARY}` : '1.5px dashed rgba(255,255,255,0.18)',
              background: 'radial-gradient(circle at 30% 25%, #14424d, #061418)',
              color: sealed ? CLR_PRIMARY : 'rgba(255,255,255,0.45)',
              display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 6,
              cursor: sealed ? 'pointer' : 'default',
            }}
          >
            <span style={{ width: 34, height: 34, borderRadius: '50%', border: '2px dashed currentColor', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 800, fontSize: '0.95rem' }}>1</span>
            <span style={{ fontSize: '0.78rem', fontWeight: 700 }}>{isMe ? 'أُرسل · مرة واحدة' : viewed ? 'تمت المشاهدة' : 'Open'}</span>
            {secs > 0 && <span style={{ fontSize: '0.62rem', opacity: 0.7 }}>{scFmtSecs(secs)}</span>}
          </div>
        </ScVideoDeleteFx>
        {open && <ScOnceViewer url={url} onClose={() => setOpen(false)} />}
      </>
    );
  }

  const toggle = () => {
    const v = vidRef.current;
    if (!v) return;
    if (v.muted) {
      v.muted = false; v.loop = false; v.currentTime = 0;
      setMuted(false);
      void v.play().catch(() => { /* ignore */ });
      return;
    }
    if (v.paused) void v.play().catch(() => { /* ignore */ });
    else v.pause();
  };
  const r = SIZE / 2 - 3;
  const C = 2 * Math.PI * r;
  return (
    <ScVideoDeleteFx enabled={isMe} round onDelete={onDelete}>
      <div
        onClick={toggle}
        style={{ position: 'relative', width: SIZE, height: SIZE, borderRadius: '50%', overflow: 'hidden', background: '#000', cursor: 'pointer', boxShadow: '0 0 0 2px rgba(0,188,212,0.35)' }}
      >
        <video
          ref={vidRef} src={`${url}#t=0.1`} muted loop autoPlay playsInline preload="auto"
          onPlay={() => setPaused(false)}
          onPause={() => setPaused(true)}
          onTimeUpdate={e => { const v = e.currentTarget; if (!v.muted && v.duration) setProg(v.currentTime / v.duration); }}
          onEnded={e => {
            const v = e.currentTarget;
            v.muted = true; v.loop = true; v.currentTime = 0;
            setMuted(true); setProg(0);
            void v.play().catch(() => { /* ignore */ });
          }}
          style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', pointerEvents: 'none' }}
        />
        {!muted && (
          <svg width={SIZE} height={SIZE} style={{ position: 'absolute', inset: 0, pointerEvents: 'none', transform: 'rotate(-90deg)' }}>
            <circle cx={SIZE / 2} cy={SIZE / 2} r={r} fill="none" stroke={CLR_PRIMARY} strokeWidth={3} strokeLinecap="round" strokeDasharray={C} strokeDashoffset={C * (1 - prog)} />
          </svg>
        )}
        {paused && (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.25)', pointerEvents: 'none' }}>
            <span style={{ width: 44, height: 44, borderRadius: '50%', background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Play size={20} color="#fff" fill="#fff" />
            </span>
          </div>
        )}
        <span style={{ position: 'absolute', left: 10, bottom: 12, background: 'rgba(0,0,0,0.5)', color: '#fff', fontSize: '0.62rem', fontWeight: 600, borderRadius: 10, padding: '2px 7px', display: 'flex', alignItems: 'center', gap: 4, pointerEvents: 'none' }}>
          {muted && <VolumeX size={10} />}{secs > 0 ? scFmtSecs(secs) : ''}
        </span>
      </div>
    </ScVideoDeleteFx>
  );
}

// Round record button. Hold = record and send on release. Tap = switch audio <-> video.
// Slide sideways / up while holding = cancel. In video mode a small "1" chip toggles view-once.
function ScRecordButton({ onSendVoice, onSendVideo }: {
  onSendVoice: (blob: Blob, secs: number) => void | Promise<void>;
  onSendVideo: (blob: Blob, secs: number, once: boolean) => void | Promise<void>;
}) {
  const [mode, setMode] = useState<'audio' | 'video'>(() => {
    try { return localStorage.getItem(SC_REC_MODE_KEY) === 'video' ? 'video' : 'audio'; } catch { return 'audio'; }
  });
  const [once, setOnce] = useState<boolean>(() => {
    try { return localStorage.getItem(SC_REC_ONCE_KEY) === '1'; } catch { return false; }
  });
  const [recording, setRecording] = useState(false);
  const [secs, setSecs] = useState(0);
  const [cancelling, setCancelling] = useState(false);
  const [hint, setHint] = useState('');
  const [hintPos, setHintPos] = useState<{ left: number; top: number } | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [anchor, setAnchor] = useState<{ top: number } | null>(null);
  const btnRef = useRef<HTMLButtonElement | null>(null);
  const previewRef = useRef<HTMLVideoElement | null>(null);
  const hintTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const r = useRef({
    down: false, holdFired: false, starting: false, abort: false, cancel: false,
    recorder: null as MediaRecorder | null, chunks: [] as Blob[], stream: null as MediaStream | null,
    t0: 0, tick: null as ReturnType<typeof setInterval> | null, hold: null as ReturnType<typeof setTimeout> | null,
    sx: 0, sy: 0, mime: '', recMode: 'audio' as 'audio' | 'video', mode: 'audio' as 'audio' | 'video', once: false,
  });
  r.current.mode = mode;
  r.current.once = once;

  const showHint = (msg: string) => {
    const rc = btnRef.current?.getBoundingClientRect();
    setHintPos(rc ? { left: Math.max(8, rc.left), top: rc.top } : null);
    setHint(msg);
    if (hintTimer.current) clearTimeout(hintTimer.current);
    hintTimer.current = setTimeout(() => setHint(''), 2200);
  };

  useEffect(() => {
    const v = previewRef.current;
    if (v && stream) { v.srcObject = stream; void v.play().catch(() => { /* ignore */ }); }
  }, [stream, recording]);

  useEffect(() => () => {
    const c = r.current;
    if (c.tick) clearInterval(c.tick);
    if (c.hold) clearTimeout(c.hold);
    if (hintTimer.current) clearTimeout(hintTimer.current);
    try { c.recorder?.state !== 'inactive' && c.recorder?.stop(); } catch { /* ignore */ }
    c.stream?.getTracks().forEach(t => t.stop());
  }, []);

  const finish = async (send: boolean) => {
    const c = r.current;
    const rec = c.recorder;
    if (!rec) return;
    c.recorder = null;
    if (c.tick) { clearInterval(c.tick); c.tick = null; }
    const wantVideo = c.recMode === 'video';
    const onceFlag = c.once;
    const mime = c.mime;
    const stopped = new Promise<void>(res => { rec.onstop = () => res(); });
    try { if (rec.state !== 'inactive') rec.stop(); } catch { /* ignore */ }
    await stopped;
    const chunks = c.chunks; c.chunks = [];
    c.stream?.getTracks().forEach(t => t.stop()); c.stream = null;
    const ms = Date.now() - c.t0;
    setStream(null); setRecording(false); setCancelling(false); setSecs(0);
    if (!send) return;
    if (ms < 900) { showHint('اضغط مطولاً للتسجيل'); return; }
    const base = (mime || (wantVideo ? 'video/webm' : 'audio/webm')).split(';')[0];
    const blob = new Blob(chunks, { type: wantVideo ? base : (mime || base) });
    if (blob.size < 800) return;
    const secsFinal = Math.max(1, Math.round(ms / 1000));
    if (wantVideo) await onSendVideo(blob, secsFinal, onceFlag);
    else await onSendVoice(blob, secsFinal);
  };

  const begin = async () => {
    const c = r.current;
    if (c.starting || c.recorder) return;
    c.starting = true; c.abort = false; c.cancel = false;
    const wantVideo = c.mode === 'video';
    c.recMode = c.mode;
    let st: MediaStream;
    try {
      st = await navigator.mediaDevices.getUserMedia(
        wantVideo
          ? { audio: true, video: { facingMode: 'user', width: { ideal: 480 }, height: { ideal: 480 }, aspectRatio: { ideal: 1 } } }
          : { audio: true }
      );
    } catch {
      c.starting = false;
      showHint(wantVideo ? 'ما قدرت أفتح الكاميرا أو المايك — تأكد من الصلاحيات' : 'ما قدرت أفتح المايك — تأكد من الصلاحيات');
      return;
    }
    if (!c.down || c.abort) { st.getTracks().forEach(t => t.stop()); c.starting = false; return; }
    const cands = wantVideo
      ? ['video/mp4', 'video/webm;codecs=vp9,opus', 'video/webm;codecs=vp8,opus', 'video/webm']
      : ['audio/webm;codecs=opus', 'audio/mp4', 'audio/webm'];
    let mime = '';
    for (const m of cands) {
      try { if (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported(m)) { mime = m; break; } } catch { /* ignore */ }
    }
    let rec: MediaRecorder;
    try {
      rec = mime
        ? new MediaRecorder(st, wantVideo ? { mimeType: mime, videoBitsPerSecond: 900000, audioBitsPerSecond: 64000 } : { mimeType: mime })
        : new MediaRecorder(st);
    } catch {
      st.getTracks().forEach(t => t.stop());
      c.starting = false;
      showHint('التسجيل غير مدعوم على هذا المتصفح');
      return;
    }
    c.chunks = []; c.stream = st; c.recorder = rec; c.mime = rec.mimeType || mime;
    rec.ondataavailable = e => { if (e.data && e.data.size > 0) c.chunks.push(e.data); };
    rec.start(200);
    c.t0 = Date.now();
    const rc = btnRef.current?.getBoundingClientRect();
    setAnchor(rc ? { top: rc.top } : null);
    setStream(wantVideo ? st : null);
    setRecording(true); setSecs(0); setCancelling(false);
    c.tick = setInterval(() => {
      const s = Math.floor((Date.now() - c.t0) / 1000);
      setSecs(s);
      if (s >= SC_VNOTE_MAX_SECS) void finish(true);
    }, 250);
    c.starting = false;
    try { navigator.vibrate?.(15); } catch { /* ignore */ }
  };

  const onDown = (e: React.PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* ignore */ }
    const c = r.current;
    c.down = true; c.holdFired = false; c.cancel = false; c.sx = e.clientX; c.sy = e.clientY;
    if (c.hold) clearTimeout(c.hold);
    c.hold = setTimeout(() => { c.hold = null; c.holdFired = true; void begin(); }, 260);
  };
  const onMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    const c = r.current;
    if (!c.down || !c.recorder) return;
    const cancel = Math.abs(e.clientX - c.sx) > 90 || e.clientY - c.sy < -90;
    if (cancel !== c.cancel) { c.cancel = cancel; setCancelling(cancel); }
  };
  const release = (e: React.PointerEvent<HTMLButtonElement>, forceCancel: boolean) => {
    const c = r.current;
    if (!c.down) return;
    c.down = false;
    if (c.hold) { clearTimeout(c.hold); c.hold = null; }
    try { e.currentTarget.releasePointerCapture(e.pointerId); } catch { /* ignore */ }
    if (!c.holdFired) {
      if (forceCancel) return;
      const next = c.mode === 'audio' ? 'video' : 'audio';
      setMode(next);
      try { localStorage.setItem(SC_REC_MODE_KEY, next); } catch { /* ignore */ }
      showHint(next === 'video' ? 'اضغط مطولاً لتسجيل فيديو • انقر للتبديل للصوت' : 'اضغط مطولاً لتسجيل صوت • انقر للتبديل للفيديو');
      return;
    }
    if (c.recorder) void finish(!forceCancel && !c.cancel);
    else if (c.starting) c.abort = true;
  };

  const overlayBottom = anchor ? Math.max(12, window.innerHeight - anchor.top) : 120;
  const ModeIcon = mode === 'video' ? Video : Mic;
  return (
    <div style={{ position: 'relative', flexShrink: 0 }}>
      {mode === 'video' && !recording && (
        <button
          type="button"
          aria-label={once ? 'مرة واحدة' : 'عادي'}
          onClick={() => {
            const n = !once;
            setOnce(n);
            try { localStorage.setItem(SC_REC_ONCE_KEY, n ? '1' : '0'); } catch { /* ignore */ }
            showHint(n ? 'مرة واحدة: يختفي الفيديو بعد ما المستقبِل يشوفه' : 'عادي: ينزل الفيديو ويبقى بالشات');
          }}
          style={{
            position: 'absolute', bottom: 48, left: '50%', transform: 'translateX(-50%)',
            width: 28, height: 28, borderRadius: '50%', padding: 0, cursor: 'pointer',
            border: `1.5px dashed ${once ? CLR_PRIMARY : 'rgba(150,200,200,0.5)'}`,
            background: once ? CLR_PRIMARY : 'rgba(0,0,0,0.25)',
            color: once ? '#041018' : 'rgba(200,230,230,0.8)',
            fontWeight: 800, fontSize: '0.78rem', display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
        >1</button>
      )}
      <button
        ref={btnRef}
        type="button"
        aria-label={mode === 'video' ? 'تسجيل فيديو' : 'تسجيل صوتي'}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={e => release(e, false)}
        onPointerCancel={e => release(e, true)}
        onContextMenu={e => e.preventDefault()}
        style={{
          width: 42, height: 42, borderRadius: '50%', padding: 0, cursor: 'pointer', position: 'relative',
          border: `1px solid ${recording ? 'rgba(239,68,68,0.7)' : CLR_PRIMARY_BORDER}`,
          background: recording ? 'rgba(239,68,68,0.92)' : CLR_PRIMARY_FAINT,
          color: recording ? '#fff' : CLR_PRIMARY,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          transform: recording ? 'scale(1.35)' : 'scale(1)',
          transition: 'transform .15s ease, background .15s ease',
          zIndex: recording ? 30 : undefined,
          touchAction: 'none', userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none',
        } as React.CSSProperties}
      >
        {recording && cancelling ? <Trash2 size={17} strokeWidth={2} /> : <ModeIcon size={17} strokeWidth={2} />}
      </button>

      {hint && hintPos && createPortal(
        <div style={{
          position: 'fixed', left: hintPos.left, bottom: window.innerHeight - hintPos.top + 46, zIndex: 20000,
          background: '#1d2427', color: '#fff', fontSize: '0.72rem', borderRadius: 10, padding: '7px 11px',
          boxShadow: '0 6px 18px rgba(0,0,0,0.35)', direction: 'rtl', maxWidth: '78vw', pointerEvents: 'none',
        }}>{hint}</div>,
        document.body
      )}

      {recording && createPortal(
        <div style={{
          position: 'fixed', left: '50%', transform: 'translateX(-50%)', bottom: overlayBottom + 34, zIndex: 20000,
          display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, pointerEvents: 'none',
        }}>
          {stream && (
            <div style={{ width: 168, height: 168, borderRadius: '50%', overflow: 'hidden', background: '#000', border: `3px solid ${cancelling ? '#6b7280' : '#ef4444'}`, opacity: cancelling ? 0.55 : 1, boxShadow: '0 10px 30px rgba(0,0,0,0.45)' }}>
              <video ref={previewRef} muted playsInline autoPlay style={{ width: '100%', height: '100%', objectFit: 'cover', transform: 'scaleX(-1)', display: 'block' }} />
            </div>
          )}
          <div style={{
            display: 'flex', alignItems: 'center', gap: 8, borderRadius: 999, padding: '7px 14px',
            background: cancelling ? '#ef4444' : 'rgba(20,25,28,0.94)', color: '#fff', fontSize: '0.78rem', fontWeight: 600, direction: 'rtl',
            boxShadow: '0 6px 18px rgba(0,0,0,0.35)',
          }}>
            {cancelling
              ? <Trash2 size={14} />
              : <motion.span animate={{ opacity: [1, 0.3, 1] }} transition={{ duration: 1, repeat: Infinity }} style={{ width: 8, height: 8, borderRadius: '50%', background: '#ef4444', display: 'inline-block' }} />}
            <span style={{ direction: 'ltr' }}>{scFmtSecs(secs)}</span>
            <span style={{ opacity: 0.85 }}>{cancelling ? 'أفلت للإلغاء' : 'اسحب للإلغاء'}</span>
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}

function ScVoiceBubble({
  url,
  duration,
  isMe,
  primaryColor,
  primaryBorder,
  textDim,
  waveColor,
  playColor,
  pauseColor,
}: {
  url: string;
  duration: number | null;
  isMe: boolean;
  primaryColor: string;
  primaryBorder: string;
  textDim: string;
  waveColor?: string;
  playColor?: string;
  pauseColor?: string;
}) {
  const [playing, setPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  function toggle() {
    if (!audioRef.current) {
      audioRef.current = new Audio(url);
      audioRef.current.ontimeupdate = () => {
        const a = audioRef.current!;
        setProgress(a.duration ? a.currentTime / a.duration : 0);
        setCurrentTime(a.currentTime);
      };
      audioRef.current.onended = () => {
        setPlaying(false);
        setProgress(0);
        setCurrentTime(0);
      };
    }
    if (playing) {
      audioRef.current.pause();
      setPlaying(false);
    } else {
      audioRef.current.play();
      setPlaying(true);
    }
  }
  const barHeights = useMemo(() => {
    let seed = 0;
    for (let i = 0; i < url.length; i++) seed = seed * 31 + url.charCodeAt(i) & 0xffff;
    return Array.from({
      length: SC_BARS
    }, (_, i) => {
      seed = seed * 1664525 + 1013904223 & 0xffff;
      const base = 0.25 + seed / 0xffff * 0.75;
      const edge = Math.min(i, SC_BARS - 1 - i) / (SC_BARS / 4);
      return Math.max(0.2, base * Math.min(1, edge));
    });
  }, [url]);
  const totalSecs = duration ?? 0;
  const displaySecs = playing ? currentTime : totalSecs;
  const label = `${Math.floor(displaySecs / 60)}:${String(Math.floor(displaySecs % 60)).padStart(2, '0')}`;
  return <div style={{
    display: 'flex',
    alignItems: 'center',
    gap: 8,
    minWidth: 160,
    maxWidth: 220
  }}>
      <motion.button whileTap={{
      scale: 0.88
    }} onClick={toggle} style={{
      width: 34,
      height: 34,
      borderRadius: '50%',
      flexShrink: 0,
      background: playing ? 'rgba(239,68,68,0.12)' : (playColor ? '#fff' : (isMe ? 'rgba(0,188,212,0.2)' : 'rgba(255,255,255,0.08)')),
      border: `1.5px solid ${playing && pauseColor ? 'rgba(239,68,68,0.45)' : primaryBorder}`,
      color: playing ? (pauseColor || '#ef4444') : (playColor || primaryColor),
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
        {playing ? <Pause size={13} strokeWidth={2.5} /> : <Play size={13} strokeWidth={2.5} />}
      </motion.button>
      <div style={{
      flex: 1,
      display: 'flex',
      alignItems: 'center',
      gap: 2,
      height: 28
    }}>
        {barHeights.map((h, i) => {
        const filled = i / SC_BARS <= progress;
        return <motion.div key={i} animate={playing && Math.abs(i / SC_BARS - progress) < 1 / SC_BARS ? {
          scaleY: [1, 1.4, 0.8, 1]
        } : {
          scaleY: 1
        }} transition={{
          duration: 0.4,
          repeat: playing ? Infinity : 0,
          ease: 'easeInOut' as const
        }} style={{
          flex: 1,
          height: `${h * 100}%`,
          borderRadius: 2,
          background: filled ? (waveColor || primaryColor) : (waveColor ? 'rgba(0,0,0,0.18)' : (isMe ? 'rgba(0,188,212,0.2)' : 'rgba(255,255,255,0.12)')),
          transformOrigin: 'center',
          transition: 'background 0.1s'
        }} />;
      })}
      </div>
      <span style={{
      color: textDim,
      fontSize: '0.62rem',
      flexShrink: 0,
      minWidth: 26,
      textAlign: 'right'
    }}>{label}</span>
    </div>;
}


function formatCompactCount(n: number | string | null | undefined): string {
  const v = Number(n);
  if (!Number.isFinite(v) || v === 0) return '0';
  const sign = v < 0 ? '-' : '';
  const abs = Math.abs(v);
  const fmt = (x: number, suffix: string) => {
    const rounded = abs >= 10 ? Math.round(x) : Math.round(x * 10) / 10;
    const text = String(rounded).replace(/\.0$/, '');
    return sign + text + suffix;
  };
  if (abs < 1000) return sign + String(Math.round(abs));
  if (abs < 1000000) return fmt(abs / 1000, 'K');
  if (abs < 1000000000) return fmt(abs / 1000000, 'M');
  return fmt(abs / 1000000000, 'B');
}

function formatVideoClock(sec: number): string {
  if (!Number.isFinite(sec) || sec < 0) return '0:00';
  const s = Math.floor(sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}:${String(r).padStart(2, '0')}`;
}

/** Full-screen post video: play/pause, mute, seek bar, duration — controls at bottom */
function SinglePostVideoPlayer({ src, active }: { src: string; active: boolean }) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(true);
  const [current, setCurrent] = useState(0);
  const [duration, setDuration] = useState(0);
  const seekingRef = useRef(false);
  // Controls bar (seek/play/time/volume): auto-hides 2s after entering, tap brings it
  // back; a tap while it's visible toggles play/pause instead of hiding it again.
  const [controlsVisible, setControlsVisible] = useState(true);

  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    if (active) {
      v.currentTime = 0;
      v.muted = true;
      void v.play().then(() => {
        v.muted = false;
        setMuted(false);
        setPlaying(true);
      }).catch(() => {
        v.muted = true;
        setMuted(true);
        void v.play().then(() => setPlaying(true)).catch(() => setPlaying(false));
      });
    } else {
      v.pause();
      setPlaying(false);
    }
  }, [active, src]);

  useEffect(() => {
    if (!active) return;
    setControlsVisible(true);
  }, [active, src]);

  // Re-arms every time the bar becomes visible again (entry or tap-to-show),
  // so it keeps auto-hiding after 2s each time, not just on first entry.
  useEffect(() => {
    if (!active || !controlsVisible) return;
    const t = window.setTimeout(() => setControlsVisible(false), 2000);
    return () => window.clearTimeout(t);
  }, [active, controlsVisible]);

  useEffect(() => {
    const v = videoRef.current;
    if (v) v.muted = muted;
  }, [muted]);

  function togglePlay() {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) {
      void v.play().then(() => setPlaying(true)).catch(() => {});
    } else {
      v.pause();
      setPlaying(false);
    }
  }

  function onSeekStart() {
    seekingRef.current = true;
  }
  function onSeek(val: number) {
    const v = videoRef.current;
    if (!v || !Number.isFinite(val)) return;
    v.currentTime = val;
    setCurrent(val);
  }
  function onSeekEnd(val: number) {
    seekingRef.current = false;
    onSeek(val);
  }

  return (
    <div style={{ width: '100%', height: '100%', position: 'relative', background: '#000' }}>
      <video
        ref={videoRef}
        key={src}
        src={src}
        playsInline
        loop
        muted={muted}
        controls={false}
        onClick={e => {
          e.stopPropagation();
          if (!controlsVisible) { setControlsVisible(true); return; }
          togglePlay();
        }}
        onTimeUpdate={() => {
          const v = videoRef.current;
          if (!v || seekingRef.current) return;
          setCurrent(v.currentTime || 0);
        }}
        onLoadedMetadata={() => {
          const v = videoRef.current;
          if (v) setDuration(v.duration || 0);
        }}
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onEnded={() => setPlaying(false)}
        style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', background: '#000', cursor: 'pointer' }}
      />
      {controlsVisible && (
      <div
        onClick={e => e.stopPropagation()}
        onTouchStart={e => e.stopPropagation()}
        onTouchEnd={e => e.stopPropagation()}
        style={{
          position: 'absolute', left: 0, right: 0, bottom: 0, zIndex: 5,
          padding: '10px 12px 12px',
          background: 'linear-gradient(to top, rgba(0,0,0,0.75) 0%, rgba(0,0,0,0.35) 70%, transparent 100%)',
          display: 'flex', flexDirection: 'column', gap: 8,
        }}
      >
        <input
          type="range"
          min={0}
          max={duration > 0 ? duration : 0}
          step={0.05}
          value={Math.min(current, duration || 0)}
          onChange={e => onSeek(Number(e.target.value))}
          onMouseDown={onSeekStart}
          onMouseUp={e => onSeekEnd(Number((e.target as HTMLInputElement).value))}
          onTouchStart={onSeekStart}
          onTouchEnd={e => onSeekEnd(Number((e.target as HTMLInputElement).value))}
          aria-label="Seek"
          style={{
            width: '100%', height: 4, margin: 0, padding: 0, cursor: 'pointer',
            accentColor: '#00BCD4',
          }}
        />
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <button
            type="button"
            onClick={e => { e.stopPropagation(); togglePlay(); }}
            aria-label={playing ? 'Pause' : 'Play'}
            style={{
              width: 36, height: 36, borderRadius: '50%', border: 'none',
              background: 'rgba(255,255,255,0.12)', color: '#fff', cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 0, flexShrink: 0,
            }}
          >
            {playing ? <Pause size={16} strokeWidth={2.4} /> : <Play size={16} strokeWidth={2.4} style={{ marginLeft: 2 }} />}
          </button>
          <span style={{ color: '#fff', fontSize: '0.72rem', fontWeight: 700, fontVariantNumeric: 'tabular-nums', minWidth: 72 }}>
            {formatVideoClock(current)} / {formatVideoClock(duration)}
          </span>
          <div style={{ flex: 1 }} />
          <button
            type="button"
            onClick={e => { e.stopPropagation(); setMuted(m => !m); }}
            aria-label={muted ? 'Unmute' : 'Mute'}
            style={{
              width: 36, height: 36, borderRadius: '50%', border: 'none',
              background: 'rgba(255,255,255,0.12)', color: '#fff', cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 0, flexShrink: 0,
            }}
          >
            {muted ? <VolumeX size={16} strokeWidth={2.4} /> : <Volume2 size={16} strokeWidth={2.4} />}
          </button>
        </div>
      </div>
      )}
    </div>
  );
}

