                          backgroundImage: 'linear-gradient(105deg, #00BCD4 0%, #00BCD4 38%, #e0fbff 48%, #ffffff 52%, #e0fbff 56%, #00BCD4 68%, #00BCD4 100%)',
                          backgroundSize: '220% 100%',
